mapper.select:
SELECT a.id_documento_aceptacion ,a.numero_documento_aceptacion ,a.id_tipo_documento_aceptacion ,a.id_estado_documento_aceptacion ,a.id_orden_compra ,a.numero_orden_compra ,a.posicion_orden_compra ,a.numero_guia_proveedor ,a.proveedor_ruc ,a.proveedor_razon_social ,a.usuario_sap_recepcion ,a.usuario_sap_autoriza ,a.codigo_moneda ,a.fecha_emision ,a.fecha_aceptacion ,a.status_sap ,a.fecha_publicacion ,b.descripcion as tda_descripcion ,c.descripcion as eda_descripcion ,e.codigo_sociedad ,e.razon_social as sociedad_razon_social FROM documento_aceptacion a INNER JOIN tipo_documento_aceptacion b ON a.id_tipo_documento_aceptacion = b.id_tipo_documento_aceptacion INNER JOIN estado_documento_aceptacion c ON a.id_estado_documento_aceptacion = c.id_estado_documento_aceptacion INNER JOIN orden_compra d ON a.id_orden_compra = d.id_orden_compra INNER JOIN sociedad e ON d.sociedad = e.codigo_sociedad WHERE a.id_estado_documento_aceptacion in (1) AND a.fecha_emision between #{fechaInicio, jdbcType=DATE} AND #{fechaFin, jdbcType=DATE}
AND a.proveedor_ruc = #{ruc}
AND UPPER(a.numero_orden_compra) LIKE '%'||UPPER(#{nroOC})||'%'
AND UPPER(a.numero_guia_proveedor) LIKE '%'||UPPER(#{nroGP})||'%'
AND a.id_tipo_documento_aceptacion = #{tipoDocumento, jdbcType=INTEGER}
order by a.fecha_emision desc, a.id_documento_aceptacion desc
LIMIT #{nroRegistros} OFFSET #{paginaMostrar}

SELECT a.id_documento_aceptacion, a.numero_documento_aceptacion, a.id_tipo_documento_aceptacion, a.id_estado_documento_aceptacion, a.numero_orden_compra, a.posicion_orden_compra, a.numero_guia_proveedor, a.proveedor_ruc, a.proveedor_razon_social, a.usuario_sap_recepcion, a.usuario_sap_autoriza, a.codigo_moneda, a.fecha_emision, a.fecha_aceptacion, a.status_sap, a.fecha_publicacion, a.fecha_contabilizacion, up.fecha_emision AS fecha_emision_prefactura, up.referencia AS referencia_prefactura FROM documento_aceptacion a LEFT JOIN ( SELECT sub.id_documento_aceptacion, sub.fecha_emision, sub.referencia FROM ( SELECT b.id_documento_aceptacion, c.id_prefactura, c.fecha_emision, c.referencia, c.id_estado_prefactura, -- Se incluye para filtrar más abajo RANK() OVER (PARTITION BY b.id_documento_aceptacion ORDER BY c.id_prefactura DESC) AS rn FROM prefactura_documento_aceptacion b JOIN prefactura c ON b.id_prefactura = c.id_prefactura WHERE c.id_estado_prefactura IN (1, 2) -- Solo tomamos prefacturas con estado 1 o 2 ) sub WHERE sub.rn = 1 -- Tomamos la última prefactura ) up ON a.id_documento_aceptacion = up.id_documento_aceptacion WHERE a.id_estado_documento_aceptacion NOT IN (4)
AND a.fecha_emision BETWEEN #{fechaInicio, jdbcType=DATE} AND #{fechaFin, jdbcType=DATE}
AND a.proveedor_ruc = #{ruc}
AND UPPER(a.numero_documento_aceptacion) LIKE '%' || UPPER(#{numeroDocumentoAceptacion}) || '%'
AND UPPER(a.numero_orden_compra) LIKE '%' || UPPER(#{numeroOrdenCompra}) || '%'
AND a.numero_guia_proveedor = #{numeroGuiaProveedor}
AND a.fecha_contabilizacion BETWEEN #{fechaContabilizacionDesde, jdbcType=DATE} AND #{fechaContabilizacionHasta, jdbcType=DATE}
ORDER BY a.fecha_emision DESC, a.id_documento_aceptacion DESC
